import unittest
from unittest.mock import patch, MagicMock
from machine_learning_module import MachineLearningAlgorithm, PaymentGateway

class TestMachineLearningAlgorithm(unittest.TestCase):
    @patch('machine_learning_module.load_training_data')
    def test_train_with_initial_data(self, mock_load):
        mock_load.return_value = {'data': 'initial_data'}
        ml_algo = MachineLearningAlgorithm()
        ml_algo.train()
        mock_load.assert_called_once_with('initial_data')
        self.assertTrue(ml_algo.is_trained)

    @patch('machine_learning_module.combine_data')
    def test_combine_data(self, mock_combine):
        mock_combine.return_value = {'data': 'combined_data'}
        ml_algo = MachineLearningAlgorithm()
        ml_algo.train()
        ml_algo.combine_data('live_data')
        mock_combine.assert_called_once_with({'data': 'initial_data'}, 'live_data')
        self.assertEqual(ml_algo.data, {'data': 'combined_data'})

class TestPaymentGateway(unittest.TestCase):
    @patch('machine_learning_module.PaymentGateway.process_payment')
    def test_process_payment(self, mock_process):
        mock_process.return_value = True
        pg = PaymentGateway()
        result = pg.process_payment('card_info', 100)
        mock_process.assert_called_once_with('card_info', 100)
        self.assertTrue(result)

    @patch('machine_learning_module.PaymentGateway.process_payment')
    def test_process_payment_failure(self, mock_process):
        mock_process.return_value = False
        pg = PaymentGateway()
        with self.assertRaises(Exception):
            pg.process_payment('card_info', 100)

if __name__ == '__main__':
    unittest.main()
